/**
 * Rewrite `## Overview` → `## Summary` at the positionally-paired collision
 * indices in an EN body (F2 EN-side convergence). When an existing EN
 * `## Overview` is the package's overview, the generator renames it to
 * `## Summary` so the doc-standard `^## Summary$` requirement is satisfied
 * by the renamed heading WITHOUT inserting a separate Summary — the
 * Overview content consolidates under Summary. The ZH sibling keeps its
 * existing `## 概述` (already satisfies `^## 概述$`). Idempotent: a heading
 * already renamed to `## Summary` no longer matches `Overview` and is left
 * alone. Mirrors insertAnchorsBeforeHeadings' heading-cursor pattern.
 */
function renameEnOverviewToSummary(
  source: string,
  enHeadings: readonly string[],
): string {
  const collisionIndices = new Set<number>()
  for (let i = 0; i < enHeadings.length; i++) {
    if (enHeadings[i] === 'Overview') collisionIndices.add(i)
  }
  if (collisionIndices.size === 0) return source

  const lines = source.split('\n')
  let headingCursor = 0
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (line === undefined) continue
    const headingMatch = /^## (.+)$/.exec(line)
    if (headingMatch !== null) {
      if (collisionIndices.has(headingCursor) && headingMatch[1]?.trim() === 'Overview') {
        lines[i] = `## ${EN_HEADINGS.summary}`
      }
      headingCursor += 1
    }
  }
  return lines.join('\n')
}

